{"command":"cat package.json; mkdir -p src; cat > src/cli.js <<'EOF'
import { readFileSync } from 'node:fs'

function fail(msg) {
  process.stderr.write(`error: ${msg}\n`)
  process.exit(2)
}

function changesOf(base, side) {
  const n = base.length, m = side.length
  const L = Array.from({ length: n + 1 }, () => new Int32Array(m + 1))
  for (let i = n - 1; i >= 0; i--) {
    for (let j = m - 1; j >= 0; j--) {
      L[i][j] = base[i] === side[j] ? L[i + 1][j + 1] + 1 : Math.max(L[i + 1][j], L[i][j + 1])
    }
  }
  const out = []
  let i = 0, j = 0, bs = 0, ss = 0
  const flush = () => {
    if (i > bs || j > ss) out.push({ bs, be: i, ss, se: j })
  }
  while (i < n && j < m) {
    if (base[i] === side[j]) {
      flush()
      i++; j++
      bs = i; ss = j
    } else if (L[i + 1][j] >= L[i][j + 1]) i++
    else j++
  }
  i = n; j = m
  flush()
  return out
}

const eq = (a, b) => a.length === b.length && a.every((x, k) => x === b[k])

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !['merge', 'merge2', 'regions'].includes(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const docs = [[]]
  for (const l of lines) {
    if (l === '%%%') docs.push([])
    else docs[docs.length - 1].push(l)
  }
  if (docs.length !== 3) fail('expected three parts separated by %%%')
  const [mine, base, theirs] = docs

  const all = [
    ...changesOf(base, mine).map(c => ({ ...c, side: 0 })),
    ...changesOf(base, theirs).map(c => ({ ...c, side: 1 })),
  ]
  all.sort((a, b) => a.bs - b.bs || a.side - b.side)

  const out = []
  const items = [] // {kind, lines, base?, mine?, theirs?}
  let pos = 0, k = 0
  while (k < all.length) {
    const rs = all[k].bs
    let re = all[k].be
    const group = [all[k++]]
    while (k < all.length && all[k].bs <= re) {
      re = Math.max(re, all[k].be)
      group.push(all[k++])
    }
    if (rs > pos) items.push({ kind: 'stable', lines: base.slice(pos, rs) })
    pos = re
    const baseLines = base.slice(rs, re)
    if (group.length === 1) {
      const c = group[0]
      items.push(c.side === 0
        ? { kind: 'mine', lines: mine.slice(c.ss, c.se) }
        : { kind: 'theirs', lines: theirs.slice(c.ss, c.se) })
      continue
    }
    const repl = (side, doc) => {
      const cs = group.filter(c => c.side === side)
      if (!cs.length) return baseLines
      const lo = Math.min(...cs.map(c => c.bs)), hi = Math.max(...cs.map(c => c.be))
      const first = cs[0], last = cs[cs.length - 1]
      return doc.slice(first.ss - (lo - rs), last.se + (re - hi))
    }
    const m = repl(0, mine), t = repl(1, theirs)
    if (eq(m, t)) items.push({ kind: 'both', lines: m })
    else if (eq(m, baseLines)) items.push({ kind: 'theirs', lines: t })
    else if (eq(t, baseLines)) items.push({ kind: 'mine', lines: m })
    else items.push({ kind: 'conflict', lines: m, base: baseLines, theirs: t })
  }
  if (pos < base.length) items.push({ kind: 'stable', lines: base.slice(pos) })

  let conflict = false
  for (const it of items) {
    if (it.kind === 'conflict') conflict = true
    if (mode === 'regions') {
      out.push(it.kind === 'conflict'
        ? `conflict mine=${it.lines.length} base=${it.base.length} theirs=${it.theirs.length}`
        : `${it.kind} ${it.lines.length}`)
    } else if (it.kind === 'conflict') {
      out.push('<<<<<<< mine', ...it.lines)
      if (mode === 'merge') out.push('||||||| base', ...it.base)
      out.push('=======', ...it.theirs, '>>>>>>> theirs')
    } else out.push(...it.lines)
  }
  process.stdout.write(out.map(l => l + '\n').join(''))
  process.exitCode = conflict ? 1 : 0
}
main()
