{"file_path":"src/cli.js","content":"import { readFileSync } from 'node:fs'
import { scan } from './scan.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'tokens' && mode !== 'stats') {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}
const input = readFileSync(0, 'utf8')
const res = scan(input)
if (res.error) {
  process.stderr.write(`error: ${res.error.line}:${res.error.col}: ${res.error.reason}\n`)
  process.exit(2)
}
let out = ''
if (mode === 'tokens') {
  for (const t of res.tokens) {
    const body = t.kind === 'string' || t.kind === 'rawstring' ? JSON.stringify(t.value) : t.text
    out += `${t.line}:${t.col} ${t.kind} ${body}\n`
  }
} else {
  const counts = { ident: 0, keyword: 0, number: 0, punct: 0, rawstring: 0, string: 0 }
  for (const t of res.tokens) counts[t.kind]++
  for (const k of Object.keys(counts)) out += `${k} ${counts[k]}\n`
  out += `total ${res.tokens.length}\n`
}
process.stdout.write(out)
"}

{"file_path":"src/scan.js","content":"const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])
const PUNCT2 = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const PUNCT1 = new Set('+-*/%=<>!(){}[],;.')

const isDigit = (c) => c !== undefined && c >= '0' && c <= '9'
const isLetter = (c) => c !== undefined && ((c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z'))
const isIdStart = (c) => isLetter(c) || c === '_'
const isIdPart = (c) => isIdStart(c) || isDigit(c)
const isHex = (c) => c !== undefined && /^[0-9a-fA-F]$/.test(c)
const isBin = (c) => c === '0' || c === '1'
const isOct = (c) => c !== undefined && c >= '0' && c <= '7'

export function scan(src) {
  const cs = Array.from(src)
  const n = cs.length
  const tokens = []
  let i = 0
  let line = 1
  let col = 1

  const adv = () => {
    const c = cs[i++]
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = Math.floor((col - 1) / 4) * 4 + 5
    } else col++
    return c
  }
  const fail = (l, c, reason) => ({ error: { line: l, col: c, reason } })

  while (i < n) {
    const c = cs[i]
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      adv()
      continue
    }
    const sl = line
    const sc = col
    const start = i
    const tok = (kind, extra = {}) => tokens.push({ kind, line: sl, col: sc, text: cs.slice(start, i).join(''), ...extra })

    if (c === '/' && cs[i + 1] === '/') {
      while (i < n && cs[i] !== '\n') adv()
      continue
    }
    if (c === '/' && cs[i + 1] === '*') {
      let depth = 0
      do {
        if (i >= n) return fail(sl, sc, 'unterminated block comment')
        if (cs[i] === '/' && cs[i + 1] === '*') {
          depth++
          adv()
          adv()
        } else if (cs[i] === '*' && cs[i + 1] === '/') {
          depth--
          adv()
          adv()
        } else adv()
      } while (depth > 0)
      continue
    }
    if (c === 'r' && cs[i + 1] === '"') {
      adv()
      adv()
      let v = ''
      while (i < n && cs[i] !== '"') v += adv()
      if (i >= n) return fail(sl, sc, 'unterminated string')
      adv()
      tok('rawstring', { value: v })
      continue
    }
    if (isIdStart(c)) {
      while (i < n && isIdPart(cs[i])) adv()
      const text = cs.slice(start, i).join('')
      tok(KEYWORDS.has(text) ? 'keyword' : 'ident')
      continue
    }
    if (isDigit(c)) {
      // consume a run of digits with single underscores between digits
      const run = (pred) => {
        let count = 0
        while (i < n) {
          if (pred(cs[i])) {
            adv()
            count++
          } else if (cs[i] === '_' && count > 0 && pred(cs[i + 1])) adv()
          else break
        }
        return count
      }
      let bad = false
      const p = cs[i + 1]
      if (c === '0' && p !== undefined && 'xXbBoO'.includes(p)) {
        adv()
        adv()
        const pred = 'xX'.includes(p) ? isHex : 'bB'.includes(p) ? isBin : isOct
        if (run(pred) === 0) bad = true
      } else {
        run(isDigit)
        if (cs[i] === '.' && isDigit(cs[i + 1])) {
          adv()
          run(isDigit)
        }
        if (cs[i] === 'e' || cs[i] === 'E') {
          if (isDigit(cs[i + 1])) {
            adv()
            run(isDigit)
          } else if ((cs[i + 1] === '+' || cs[i + 1] === '-') && isDigit(cs[i + 2])) {
            adv()
            adv()
            run(isDigit)
          }
        }
      }
      if (bad || isIdPart(cs[i])) {
        while (i < n && isIdPart(cs[i])) adv()
        return fail(sl, sc, `invalid number ${cs.slice(start, i).join('')}`)
      }
      tok('number')
      continue
    }
    if (c === '"') {
      adv()
      let v = ''
      for (;;) {
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const ch = cs[i]
        if (ch === '"') {
          adv()
          break
        }
        if (ch === '\n') return fail(line, col, 'newline in string')
        if (ch !== '\\') {
          v += adv()
          continue
        }
        const bl = line
        const bc = col
        adv()
        if (i >= n) return fail(sl, sc, 'unterminated string')
        const e = cs[i]
        const simple = { n: '\n', t: '\t', r: '\r', '\\': '\\', '"': '"', 0: '\0' }
        if (Object.hasOwn(simple, e)) {
          adv()
          v += simple[e]
        } else if (e === 'x') {
          if (isHex(cs[i + 1]) && isHex(cs[i + 2])) {
            adv()
            v += String.fromCharCode(parseInt(cs[i] + cs[i + 1], 16))
            adv()
            adv()
          } else return fail(bl, bc, 'invalid escape \\x')
        } else if (e === 'u') {
          let j = i + 1
          if (cs[j] !== '{') return fail(bl, bc, 'invalid escape \\u')
          j++
          let h = ''
          while (isHex(cs[j])) h += cs[j++]
          if (h === '' || cs[j] !== '}' || parseInt(h, 16) > 0x10ffff) return fail(bl, bc, 'invalid escape \\u')
          while (i <= j) adv()
          v += String.fromCodePoint(parseInt(h, 16))
        } else return fail(bl, bc, `invalid escape \\${e}`)
      }
      tok('string', { value: v })
      continue
    }
    const two = c + (cs[i + 1] ?? '')
    if (PUNCT2.has(two)) {
      adv()
      adv()
      tok('punct')
      continue
    }
    if (PUNCT1.has(c)) {
      adv()
      tok('punct')
      continue
    }
    return fail(sl, sc, `unexpected character ${c}`)
  }
  return { tokens }
}
"}

