{"file_path":"src/parse.js","content":"// Returns an AST, or null when the grammar does not accept the formula.
// A formula with a range outside a direct function argument gets {t:'bad'} wrapper flag.
function tokenize(s) {
  const toks = []
  let i = 0
  while (i < s.length) {
    const c = s[i]
    if (c === ' ' || c === '\t') { i++; continue }
    let m
    if ((m = /^[0-9]+(\.[0-9]+)?/.exec(s.slice(i)))) {
      toks.push({ k: 'num', v: Number(m[0]) }); i += m[0].length; continue
    }
    if ((m = /^[A-Za-z][A-Za-z0-9]*/.exec(s.slice(i)))) {
      toks.push({ k: 'word', v: m[0] }); i += m[0].length; continue
    }
    if ((m = /^(<>|<=|>=|[=<>+\-*\/^(),:])/.exec(s.slice(i)))) {
      toks.push({ k: 'op', v: m[0] }); i += m[0].length; continue
    }
    return null
  }
  return toks
}

export function parseFormula(body) {
  const toks = tokenize(body)
  if (!toks) return null
  let p = 0
  const fail = () => { throw new SyntaxError('x') }
  const isOp = (v) => p < toks.length && toks[p].k === 'op' && toks[p].v === v

  function cmp() {
    let l = add()
    while (p < toks.length && toks[p].k === 'op' && ['=', '<>', '<', '<=', '>', '>='].includes(toks[p].v)) {
      const op = toks[p++].v
      l = { t: 'bin', op, l, r: add() }
    }
    return l
  }
  function add() {
    let l = mul()
    while (isOp('+') || isOp('-')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: mul() } }
    return l
  }
  function mul() {
    let l = pow()
    while (isOp('*') || isOp('/')) { const op = toks[p++].v; l = { t: 'bin', op, l, r: pow() } }
    return l
  }
  function pow() {
    const l = unary()
    if (isOp('^')) { p++; return { t: 'bin', op: '^', l, r: pow() } }
    return l
  }
  function unary() {
    if (isOp('-') || isOp('+')) { const op = toks[p++].v; return { t: 'un', op, e: unary() } }
    return primary()
  }
  function primary() {
    if (p >= toks.length) fail()
    const tk = toks[p++]
    if (tk.k === 'num') return { t: 'num', v: tk.v }
    if (tk.k === 'op') {
      if (tk.v === '(') {
        const e = cmp()
        if (!isOp(')')) fail()
        p++
        return { t: 'group', e }
      }
      fail()
    }
    const name = tk.v
    if (isOp('(')) {
      p++
      const args = []
      if (isOp(')')) p++
      else {
        for (;;) {
          args.push(cmp())
          if (isOp(',')) { p++; continue }
          if (isOp(')')) { p++; break }
          fail()
        }
      }
      return { t: 'call', name: name.toUpperCase(), args }
    }
    if (isOp(':')) {
      p++
      if (p >= toks.length || toks[p].k !== 'word') fail()
      return { t: 'range', a: name, b: toks[p++].v }
    }
    const up = name.toUpperCase()
    if (up === 'TRUE') return { t: 'bool', v: true }
    if (up === 'FALSE') return { t: 'bool', v: false }
    return { t: 'ref', a: name }
  }

  let ast
  try {
    ast = cmp()
    if (p !== toks.length) return null
  } catch (e) {
    if (e instanceof SyntaxError) return null
    throw e
  }
  // a range anywhere but directly as a call argument makes the cell #ERR!
  let misplaced = false
  const walk = (n, direct) => {
    switch (n.t) {
      case 'range': if (!direct) misplaced = true; break
      case 'bin': walk(n.l, false); walk(n.r, false); break
      case 'un': case 'group': walk(n.e, false); break
      case 'call': for (const a of n.args) walk(a, true); break
    }
  }
  walk(ast, false)
  return { t: 'root', e: ast, misplaced }
