  const walk = (n) => {
    switch (n.t) {
      case 'ref': { const a = parseAddr(n.a); if (a) add(a); break }
      case 'range': { const cs = rangeCells(n); if (cs) cs.forEach(add); break }
      case 'bin': walk(n.l); walk(n.r); break
      case 'un': case 'group': walk(n.e); break
      case 'call': n.args.forEach(walk); break
    }
  }
  if (root) walk(root.e)
  return [...set.values()].sort((a, b) => a.col - b.col || a.row - b.row).map((c) => colName(c.col) + c.row)
}

function literal(content) {
  if (content === '') return 0
  if (/^-?[0-9]+(\.[0-9]+)?$/.test(content)) return Number(content)
  if (ERR_TOKENS.has(content)) return ERR(content)
  return content
}

function cmpVals(a, b) {
  const rank = (v) => (typeof v === 'number' ? 0 : typeof v === 'string' ? 1 : 2)
  const ra = rank(a), rb = rank(b)
  if (ra !== rb) return ra - rb
  if (ra === 1) {
    const x = Array.from(a), y = Array.from(b)
    for (let i = 0; i < Math.min(x.length, y.length); i++) {
      const d = x[i].codePointAt(0) - y[i].codePointAt(0)
      if (d) return d
    }
    return x.length - y.length
  }
  return Number(a) - Number(b)
}

function fmt(v) {
  if (isErr(v)) return v.err
  if (typeof v === 'boolean') return v ? 'TRUE' : 'FALSE'
  if (typeof v === 'number') return String(Number(v.toPrecision(10)))
  return v
}

export function evaluateSheet(cells) {
  const memo = new Map()
  const state = new Map()

  function cellValue(col, row) {
    const cell = cells.get(col + ',' + row)
    if (!cell) return 0
    if (memo.has(cell)) return memo.get(cell)
    if (state.get(cell)) return ERR('#CYCLE!')
    state.set(cell, true)
    let v
    if (!cell.ast) v = literal(cell.content)
    else if (cell.ast === null || cell.ast.misplaced) v = ERR('#ERR!')
    else v = ev(cell.ast.e)
    state.set(cell, false)
    memo.set(cell, v)
    return v
  }

  const num = (v) => (typeof v === 'boolean' ? (v ? 1 : 0) : typeof v === 'string' ? ERR('#VALUE!') : v)
  const fin = (x) => (Number.isFinite(x) ? x : ERR('#DIV/0!'))

  function argValues(args) {
    const vals = []
    for (const a of args) {
      if (a.t === 'range') {
        const cs = rangeCells(a)
        if (!cs) vals.push(ERR('#REF!'))
        else for (const c of cs) vals.push(cellValue(c.col, c.row))
      } else vals.push(ev(a))
    }
    return vals
  }

  function ev(n) {
    switch (n.t) {
      case 'num': return n.v
      case 'bool': return n.v
      case 'group': return ev(n.e)
      case 'range': return ERR('#ERR!')
      case 'ref': {
        const a = parseAddr(n.a)
        return a ? cellValue(a.col, a.row) : ERR('#REF!')
      }
      case 'un': {
        const v = ev(n.e)
        if (isErr(v)) return v
        const x = num(v)
        if (isErr(x)) return x
        return n.op === '-' ? -x : x
      }
      case 'bin': {
        const l = ev(n.l)
        if (isErr(l)) return l
        const r = ev(n.r)
        if (isErr(r)) return r
        if (['=', '<>', '<', '<=', '>', '>='].includes(n.op)) {
          const d = cmpVals(l, r)
          switch (n.op) {
            case '=': return d === 0
            case '<>': return d !== 0
            case '<': return d < 0
            case '<=': return d <= 0
            case '>': return d > 0
            default: return d >= 0
          }
        }
        const x = num(l)
        if (isErr(x)) return x
        const y = num(r)
        if (isErr(y)) return y
        switch (n.op) {
          case '+': return fin(x + y)
          case '-': return fin(x - y)
          case '*': return fin(x * y)
          case '/': return y === 0 ? ERR('#DIV/0!') : fin(x / y)
          default: return fin(Math.pow(x, y))
        }
      }
      case 'call': return call(n)
    }
  }

  function call(n) {
    const name = n.name, args = n.args
    if (name === 'IF') {
      if (args.length !== 3) return ERR('#ERR!')
      const c = ev(args[0])
      if (isErr(c)) return c
      if (typeof c === 'string') return ERR('#VALUE!')
      return ev(c === true || (typeof c === 'number' && c !== 0) ? args[1] : args[2])
    }
    if (name === 'ABS') {
      if (args.length !== 1) return ERR('#ERR!')
      const vals = argValues(args)
      const e = vals.find(isErr)
      if (e) return e
      if (vals.length !== 1) return ERR('#ERR!')
      const x = num(vals[0])
      return isErr(x) ? x : Math.abs(x)
    }
    if (!['SUM', 'MIN', 'MAX', 'COUNT', 'AVG'].includes(name)) return ERR('#NAME?')
    if (args.length < 1) return ERR('#ERR!')
    const vals = argValues(args)
    const e = vals.find(isErr)
    if (e) return e
    if (name === 'COUNT') return vals.filter((v) => typeof v === 'number').length
    const xs = []
    for (const v of vals) {
      const x = num(v)
      if (isErr(x)) return x
      xs.push(x)
    }
    switch (name) {
      case 'SUM': return fin(xs.reduce((a, b) => a + b, 0))
      case 'MIN': return Math.min(...xs)
      case 'MAX': return Math.max(...xs)
      default: return fin(xs.reduce((a, b) => a + b, 0) / xs.length)
    }
  }

  const out = new Map()
  for (const c of cells.values()) {
    if (c.ast === null && c.content[0] === '=') { memo.set(c, ERR('#ERR!')); }
  }
  for (const c of cells.values()) out.set(c, fmt(cellValue(c.col, c.row)))
  return out
}
"}

