import { readFileSync } from 'node:fs'
import { parseFormula } from './parse.js'
import { evaluateSheet, depsOf } from './eval.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'values' && mode !== 'deps') {
  process.stderr.write('error: usage: cli.js values|deps\n')
  process.exit(2)
}

const lines = readFileSync(0, 'utf8').split('\n')
if (lines.length && lines[lines.length - 1] === '') lines.pop()

const cells = new Map()
for (let i = 0; i < lines.length; i++) {
  const rest = lines[i].replace(/^[ \t]+/, '')
  if (rest === '' || rest[0] === '#') continue
  const addr = /^[^ \t]*/.exec(rest)[0]
  const content = rest.slice(addr.length).replace(/^[ \t]+/, '')
  const am = /^([A-Za-z]{1,2})([0-9]{1,3})$/.exec(addr)
  const row = am ? Number(am[2]) : 0
  if (!am || row < 1) {
    process.stderr.write(`error: line ${i + 1}: invalid cell address ${addr}\n`)
    process.exit(2)
  }
  const letters = am[1].toUpperCase()
  const col = letters.length === 1 ? letters.charCodeAt(0) - 64 : (letters.charCodeAt(0) - 64) * 26 + letters.charCodeAt(1) - 64
  const key = col + ',' + row
  if (cells.has(key)) {
    process.stderr.write(`error: line ${i + 1}: cell ${letters}${row} is declared twice\n`)
    process.exit(2)
  }
  const isFormula = content[0] === '='
  cells.set(key, { col, row, content, name: letters + row, isFormula, ast: isFormula ? parseFormula(content.slice(1)) : null })
}

const sorted = [...cells.values()].sort((a, b) => a.col - b.col || a.row - b.row)
let out = ''
if (mode === 'values') {
  const vals = evaluateSheet(cells)
  for (const c of sorted) out += `${c.name}=${vals.get(c)}\n`
} else {
  for (const c of sorted) {
    out += c.name + ':'
    if (c.ast) for (const d of depsOf(c.ast)) out += ' ' + d
    out += '\n'
  }
}
process.stdout.write(out)
"}

