const NAME = /^[A-Za-z0-9_-]+$/
const COUNT = /^[1-9][0-9]*$/
const fail = (n, msg) => new Error(n === null ? `error: ${msg}` : `error: line ${n}: ${msg}`)

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  let candidates = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const n = i + 1
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const t = line.split(/\s+/)
    if (t[0] === 'candidates') {
      if (candidates !== null || ballots.length > 0) throw fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 2) throw fail(n, 'expected candidates <name>...')
      const seen = new Set()
      for (const name of t.slice(1)) {
        if (!NAME.test(name)) throw fail(n, `invalid candidate name ${name}`)
        if (seen.has(name)) throw fail(n, `candidate ${name} is declared twice`)
        seen.add(name)
      }
      candidates = t.slice(1)
    } else if (t[0] === 'ballot') {
      if (candidates === null) throw fail(n, 'candidates must be declared once, before any ballot')
      if (t.length < 3) throw fail(n, 'expected ballot <count> <candidate>...')
      if (!COUNT.test(t[1])) throw fail(n, 'count must be a positive integer')
      const seen = new Set()
      for (const name of t.slice(2)) {
        if (!candidates.includes(name)) throw fail(n, `unknown candidate ${name}`)
        if (seen.has(name)) throw fail(n, `candidate ${name} is repeated`)
        seen.add(name)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else throw fail(n, `unknown directive ${t[0]}`)
  }
  if (candidates === null) throw fail(null, 'no candidates')
  return { candidates, ballots }
}

export function count({ candidates, ballots }) {
  const continuing = new Set(candidates)
  const history = new Map(candidates.map((c) => [c, []]))
  const rounds = []
  for (;;) {
    const votes = new Map([...continuing].map((c) => [c, 0n]))
    let active = 0n
    let total = 0n
    for (const b of ballots) {
      total += b.count
      const c = b.prefs.find((p) => continuing.has(p))
      if (c !== undefined) {
        votes.set(c, votes.get(c) + b.count)
        active += b.count
      }
    }
    for (const [c, v] of votes) history.get(c).push(v)
    const list = [...votes].sort((a, b) => (a[1] > b[1] ? -1 : a[1] < b[1] ? 1 : a[0] < b[0] ? -1 : a[0] > b[0] ? 1 : 0))
    const round = { list: list.map(([c, v]) => [c, v.toString()]), exhausted: (total - active).toString() }
    rounds.push(round)
    if (active === 0n) return { rounds, winner: null }
    for (const [c, v] of votes) if (v * 2n > active) return { rounds, winner: c }
    let min = list[list.length - 1][1]
    let tied = list.filter(([, v]) => v === min).map(([c]) => c)
    const nr = rounds.length
    outer: while (tied.length > 1) {
      for (let r = 0; r < nr; r++) {
        const vs = tied.map((c) => history.get(c)[r])
        const lo = vs.reduce((a, b) => (b < a ? b : a))
        if (vs.some((v) => v !== lo)) {
          tied = tied.filter((c) => history.get(c)[r] === lo)
          continue outer
        }
      }
      break
    }
    const el = tied.reduce((a, b) => (b > a ? b : a))
    round.eliminated = el
    continuing.delete(el)
  }
}
