#!/usr/bin/env node
/**
 * The command. `node src/cli.js replay` verdicts every event of the limiter
 * file read from standard input, and `node src/cli.js summary` totals the
 * verdicts per key.
 */
import { readFileSync } from 'node:fs'
import { parse, ParseError } from './parse.js'
import { run } from './simulate.js'

const mode = process.argv.length === 3 ? process.argv[2] : null
if (mode !== 'replay' && mode !== 'summary') {
  process.stderr.write('error: usage: cli.js replay|summary\n')
  process.exit(2)
}
try {
  const model = parse(readFileSync(0, 'utf8'))
  process.stdout.write(run(model, mode))
} catch (e) {
  if (!(e instanceof ParseError)) throw e
  process.stderr.write(`error: ${e.message}\n`)
  process.exit(2)
}
EOF
cat > src/parse.js <<'EOF'
export class ParseError extends Error {}

const WORD = /^[A-Za-z0-9_./:-]+$/
const INT = /^(0|[1-9][0-9]*)$/

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const policies = new Map()
  const routes = new Map()
  const events = []
  let lastTick = null
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const f = line.split(/\s+/)
    const fail = (r) => { throw new ParseError(`line ${i + 1}: ${r}`) }
    const int = (name, v, least) => {
      if (!INT.test(v) || BigInt(v) < BigInt(least)) fail(`${name} must be an integer of at least ${least}`)
      return BigInt(v)
    }
    const decl = () => { if (events.length) fail('declarations must come before the first event') }
    const pname = (n) => { if (!WORD.test(n)) fail(`invalid policy name ${n}`) }
    switch (f[0]) {
      case 'bucket': {
        if (f.length !== 5) fail('expected bucket <name> <capacity> <refill> <per>')
        decl(); pname(f[1])
        const capacity = int('capacity', f[2], 1)
        const refill = int('refill', f[3], 0)
        const per = int('per', f[4], 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'bucket', name: f[1], capacity, refill, per })
        break
      }
      case 'window': {
        if (f.length !== 4) fail('expected window <name> <limit> <span>')
        decl(); pname(f[1])
        const limit = int('limit', f[2], 0)
        const span = int('span', f[3], 1)
        if (policies.has(f[1])) fail(`policy ${f[1]} is declared twice`)
        policies.set(f[1], { kind: 'window', name: f[1], limit, span })
        break
      }
      case 'route': {
        if (f.length < 3) fail('expected route <prefix> <policy>...')
        decl()
        if (!WORD.test(f[1])) fail(`invalid route prefix ${f[1]}`)
        if (routes.has(f[1])) fail(`prefix ${f[1]} is routed twice`)
        const list = f.slice(2).map((n) => {
          if (!policies.has(n)) fail(`unknown policy ${n}`)
          return policies.get(n)
        })
        routes.set(f[1], list)
        break
      }
      case 'event': {
        if (f.length !== 3) fail('expected event <tick> <key>')
        const tick = int('tick', f[1], 0)
        if (!WORD.test(f[2])) fail(`invalid key ${f[2]}`)
        if (lastTick !== null && tick < lastTick) fail(`tick ${tick} is before tick ${lastTick}`)
        lastTick = tick
        events.push({ tick, key: f[2] })
        break
      }
      default:
        fail(`unknown directive ${f[0]}`)
    }
  })
  return { routes, events }
}
EOF
cat > src/simulate.js <<'EOF'
// Bucket levels are kept scaled by `per` so fractions stay exact.
function newState(p, tick) {
  return p.kind === 'bucket'
    ? { level: p.capacity * p.per, last: tick }
    : { ticks: [] }
}
function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const cap = p.capacity * p.per
    s.level += p.refill * (tick - s.last)
    if (s.level > cap) s.level = cap
    s.last = tick
  } else {
    const cut = tick - p.span
    while (s.ticks.length && s.ticks[0] <= cut) s.ticks.shift()
  }
}
const allows = (p, s) => (p.kind === 'bucket' ? s.level >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.kind === 'bucket') s.level -= p.per
  else s.ticks.push(tick)
}

export function run({ routes, events }, mode) {
  const states = new Map()
  const counts = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, list] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
    }
    let denier = null
    if (best) {
      const ss = best.list.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, newState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < ss.length; i++) {
        if (!allows(best.list[i], ss[i])) { denier = best.list[i].name; break }
      }
      if (denier === null) best.list.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    out += `${tick} ${key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
  }
  if (mode === 'replay') return out
  let s = ''
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    s += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
  }
  return s + `total allowed=${ta} denied=${td}\n`
}
EOF
