// Bucket levels are kept scaled by `per` so fractions stay exact.
function newState(p, tick) {
  return p.kind === 'bucket'
    ? { level: p.capacity * p.per, last: tick }
    : { ticks: [] }
}
function advance(p, s, tick) {
  if (p.kind === 'bucket') {
    const cap = p.capacity * p.per
    s.level += p.refill * (tick - s.last)
    if (s.level > cap) s.level = cap
    s.last = tick
  } else {
    const cut = tick - p.span
    while (s.ticks.length && s.ticks[0] <= cut) s.ticks.shift()
  }
}
const allows = (p, s) => (p.kind === 'bucket' ? s.level >= p.per : BigInt(s.ticks.length) < p.limit)
function record(p, s, tick) {
  if (p.kind === 'bucket') s.level -= p.per
  else s.ticks.push(tick)
}

export function run({ routes, events }, mode) {
  const states = new Map()
  const counts = new Map()
  let out = ''
  let ta = 0
  let td = 0
  for (const { tick, key } of events) {
    let best = null
    for (const [prefix, list] of routes) {
      if (key.startsWith(prefix) && (best === null || prefix.length > best.length)) best = { length: prefix.length, list }
    }
    let denier = null
    if (best) {
      const ss = best.list.map((p) => {
        const id = p.name + '\0' + key
        if (!states.has(id)) states.set(id, newState(p, tick))
        const s = states.get(id)
        advance(p, s, tick)
        return s
      })
      for (let i = 0; i < ss.length; i++) {
        if (!allows(best.list[i], ss[i])) { denier = best.list[i].name; break }
      }
      if (denier === null) best.list.forEach((p, i) => record(p, ss[i], tick))
    }
    const c = counts.get(key) || { a: 0, d: 0 }
    counts.set(key, c)
    if (denier === null) { c.a++; ta++ } else { c.d++; td++ }
    out += `${tick} ${key} ${denier === null ? 'allow' : 'deny ' + denier}\n`
  }
  if (mode === 'replay') return out
  let s = ''
  for (const k of [...counts.keys()].sort((x, y) => (x < y ? -1 : x > y ? 1 : 0))) {
    s += `${k} allowed=${counts.get(k).a} denied=${counts.get(k).d}\n`
  }
  return s + `total allowed=${ta} denied=${td}\n`
}
