  if (args[0] === 'pack') {
    out = pack(g, workers)
  } else {
    const r = times(g)
    if (args[0] === 'waves') {
      const waves = []
      for (const k of g.names) (waves[r.depth.get(k)] ??= []).push(k)
      waves.forEach((ws, i) => {
        out += `wave ${i}: ${ws.join(' ')}\n`
      })
    } else {
      for (const k of g.names) out += `${k} start=${r.start.get(k)} finish=${r.finish.get(k)} depth=${r.depth.get(k)}\n`
    }
    out += `total ${r.total}\n`
  }
  process.stdout.write(out)
}

try {
  main()
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = e.code
}
