    s.tokens += p.refill * (tick - s.last)
    const max = p.capacity * p.per
    if (s.tokens > max) s.tokens = max
    s.last = tick
  } else {
    const cut = tick - p.span
    s.ticks = s.ticks.filter((x) => x > cut)
  }
}
const allows = (p, s) => (p.kind === 'bucket' ? s.tokens >= p.per : BigInt(s.ticks.length) < p.limit)
const record = (p, s, tick) => {
  if (p.kind === 'bucket') s.tokens -= p.per
  else s.ticks.push(tick)
}

const prefixes = [...routes.keys()]
const out = []
const counts = new Map()
let ta = 0, td = 0
for (const [tick, key] of events) {
  let best = null
  for (const p of prefixes) if (key.startsWith(p) && (best === null || p.length > best.length)) best = p
  let denied = null
  if (best !== null) {
    const list = routes.get(best)
    const sts = list.map((p) => {
      const s = state(p, key, tick)
      advance(p, s, tick)
      return s
    })
    for (let i = 0; i < list.length; i++) if (!allows(list[i], sts[i])) { denied = list[i]; break }
    if (!denied) list.forEach((p, i) => record(p, sts[i], tick))
  }
  const c = counts.get(key) || [0, 0]
  if (denied) { c[1]++; td++ } else { c[0]++; ta++ }
  counts.set(key, c)
  if (mode === 'replay') out.push(`${tick} ${key} ${denied ? 'deny ' + denied.name : 'allow'}`)
}
if (mode === 'summary') {
  for (const k of [...counts.keys()].sort((a, b) => (a < b ? -1 : a > b ? 1 : 0)))
    out.push(`${k} allowed=${counts.get(k)[0]} denied=${counts.get(k)[1]}`)
  out.push(`total allowed=${ta} denied=${td}`)
}
