import { readFileSync } from 'node:fs'

class Fail extends Error {}

function parse(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  let names = null
  const ballots = []
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].trim()
    if (line === '' || line.startsWith('#')) continue
    const n = i + 1
    const t = line.split(/\s+/)
    const fail = (m) => { throw new Fail(`error: line ${n}: ${m}`) }
    if (t[0] === 'candidates') {
      if (names !== null || ballots.length) fail('candidates must be declared once, before any ballot')
      if (t.length < 2) fail('expected candidates <name>...')
      names = []
      for (const c of t.slice(1)) {
        if (!/^[A-Za-z0-9_-]+$/.test(c)) fail(`invalid candidate name ${c}`)
        if (names.includes(c)) fail(`candidate ${c} is declared twice`)
        names.push(c)
      }
    } else if (t[0] === 'ballot') {
      if (names === null) fail('candidates must be declared once, before any ballot')
      if (t.length < 3) fail('expected ballot <count> <candidate>...')
      if (!/^[1-9][0-9]*$/.test(t[1])) fail('count must be a positive integer')
      const seen = new Set()
      for (const c of t.slice(2)) {
        if (!names.includes(c)) fail(`unknown candidate ${c}`)
        if (seen.has(c)) fail(`candidate ${c} is repeated`)
        seen.add(c)
      }
      ballots.push({ count: BigInt(t[1]), prefs: t.slice(2) })
    } else fail(`unknown directive ${t[0]}`)
  }
  if (names === null) throw new Fail('error: no candidates')
  return { names, ballots }
}

function count({ names, ballots }) {
  const alive = new Set(names)
  const history = []
  const out = []
  let winner = null
  for (;;) {
    const c = new Map([...alive].map((x) => [x, 0n]))
    let active = 0n
    for (const b of ballots) {
      const f = b.prefs.find((p) => alive.has(p))
      if (f !== undefined) { c.set(f, c.get(f) + b.count); active += b.count }
    }
    const total = ballots.reduce((s, b) => s + b.count, 0n)
    history.push(c)
    const round = { list: [...alive].sort((a, b) => (c.get(a) === c.get(b) ? (a < b ? -1 : 1) : c.get(a) > c.get(b) ? -1 : 1)), c, exhausted: total - active, elim: null }
    out.push(round)
    if (active === 0n) break
    const w = [...alive].find((x) => c.get(x) * 2n > active)
    if (w !== undefined) { winner = w; break }
    let S = [...alive]
    const min = (arr, r) => arr.reduce((m, x) => (history[r].get(x) < m ? history[r].get(x) : m), history[r].get(arr[0]))
    let r = 0
    while (r < history.length && S.length > 1) {
      const m = min(S, r)
      const keep = S.filter((x) => history[r].get(x) === m)
      if (keep.length < S.length) { S = keep; r = 0 } else r++
    }
    const e = S.sort()[S.length - 1]
    round.elim = e
    alive.delete(e)
  }
  return { out, winner }
}

const mode = process.argv.length === 3 ? process.argv[2] : null
try {
  if (mode !== 'rounds' && mode !== 'tally') throw new Fail('error: usage: cli.js rounds|tally')
  const { out, winner } = count(parse(readFileSync(0, 'utf8')))
  let s = ''
  if (mode === 'rounds') {
    out.forEach((r, i) => {
      s += `round ${i + 1}: ${r.list.map((x) => `${x}=${r.c.get(x)}`).join(' ')} exhausted=${r.exhausted}\n`
      if (r.elim) s += `eliminated ${r.elim}\n`
    })
  } else s += `rounds ${out.length}\n`
  s += winner === null ? 'no winner\n' : `winner ${winner}\n`
  process.stdout.write(s)
} catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
