import { readFileSync } from 'node:fs'
import { parseGraph, findCycle, analyze, pack } from './graph.js'

function fail(msg, code) {
  process.stderr.write(msg + '\n')
  process.exit(code)
}

const args = process.argv.slice(2)
const mode = args[0]
if (!((mode === 'waves' || mode === 'explain') && args.length === 1) && !(mode === 'pack' && args.length === 2)) {
  fail('error: usage: cli.js waves|explain|pack <workers>', 2)
}
let workers = 0
if (mode === 'pack') {
  if (!/^[1-9][0-9]*$/.test(args[1])) fail('error: workers must be a positive integer', 2)
  workers = Number(args[1])
}

let graph
try {
  graph = parseGraph(readFileSync(0, 'utf8'))
} catch (e) {
  if (e && e.userMessage) fail(e.userMessage, 2)
  throw e
}
const cycle = findCycle(graph)
if (cycle) fail('error: cycle: ' + cycle.join(' -> '), 3)

const info = analyze(graph)
const out = []
if (mode === 'waves') {
  const byDepth = []
  for (const n of info.names) (byDepth[info.depth.get(n)] ??= []).push(n)
  byDepth.forEach((ns, k) => out.push(`wave ${k}: ${ns.join(' ')}`))
  out.push(`total ${info.total}`)
} else if (mode === 'explain') {
  for (const n of info.names) {
    out.push(`${n} start=${info.start.get(n)} finish=${info.finish.get(n)} depth=${info.depth.get(n)}`)
  }
  out.push(`total ${info.total}`)
} else {
  const { lines, makespan } = pack(graph, info, workers)
  out.push(...lines, `makespan ${makespan}`)
}
