const NAME = /^[A-Za-z0-9_.-]+$/
const cmp = (a, b) => (a < b ? -1 : a > b ? 1 : 0)

function bad(msg) {
  const e = new Error(msg)
  e.userMessage = msg
  return e
}

export function parseGraph(text) {
  const lines = text.split('\n')
  if (lines.length && lines[lines.length - 1] === '') lines.pop()
  const cost = new Map()
  const deps = new Map()
  const depLines = []
  lines.forEach((raw, i) => {
    const line = raw.trim()
    if (line === '' || line.startsWith('#')) return
    const w = line.split(/\s+/)
    const n = i + 1
    if (w[0] === 'task') {
      if (w.length !== 3) throw bad(`error: line ${n}: expected task <name> <cost>`)
      if (!NAME.test(w[1])) throw bad(`error: line ${n}: invalid task name ${w[1]}`)
      if (!/^[0-9]+$/.test(w[2])) throw bad(`error: line ${n}: cost must be a non-negative integer`)
      if (cost.has(w[1])) throw bad(`error: line ${n}: task ${w[1]} is declared twice`)
      cost.set(w[1], Number(w[2]))
    } else if (w[0] === 'dep') {
      if (w.length < 3) throw bad(`error: line ${n}: expected dep <name> <dependency>...`)
      depLines.push(w.slice(1))
    } else {
      throw bad(`error: line ${n}: unknown directive ${w[0]}`)
    }
  })
  for (const names of depLines) {
    for (const nm of names) if (!cost.has(nm)) throw bad(`error: unknown task ${nm}`)
  }
  for (const nm of cost.keys()) deps.set(nm, new Set())
  for (const [name, ...ds] of depLines) for (const d of ds) deps.get(name).add(d)
  return { cost, deps }
}

export function findCycle({ cost, deps }) {
  const state = new Map() // 1 on stack, 2 done
  const names = [...cost.keys()].sort(cmp)
  for (const root of names) {
    if (state.has(root)) continue
    const stack = [root]
    const iters = [[...deps.get(root)].sort(cmp)]
    const idx = [0]
    state.set(root, 1)
    while (stack.length) {
      const top = stack.length - 1
      if (idx[top] >= iters[top].length) {
        state.set(stack[top], 2)
        stack.pop(); iters.pop(); idx.pop()
        continue
      }
      const d = iters[top][idx[top]++]
      const s = state.get(d)
      if (s === 1) return [...stack.slice(stack.indexOf(d)), d]
      if (s === undefined) {
        state.set(d, 1)
        stack.push(d)
        iters.push([...deps.get(d)].sort(cmp))
        idx.push(0)
      }
    }
  }
  return null
}

export function analyze({ cost, deps }) {
  const names = [...cost.keys()].sort(cmp)
  const rev = new Map(names.map((n) => [n, []]))
  const indeg = new Map()
  for (const n of names) {
    indeg.set(n, deps.get(n).size)
    for (const d of deps.get(n)) rev.get(d).push(n)
  }
  const order = names.filter((n) => indeg.get(n) === 0)
  for (let i = 0; i < order.length; i++) {
