    for (const d of deps.get(n)) {
      s = Math.max(s, finish.get(d))
      dp = Math.max(dp, depth.get(d) + 1)
    }
    start.set(n, s)
    finish.set(n, s + cost.get(n))
    depth.set(n, dp)
    total = Math.max(total, s + cost.get(n))
  }
  for (let i = order.length - 1; i >= 0; i--) {
    const n = order[i]
    let best = 0
    for (const m of rev.get(n)) best = Math.max(best, prio.get(m))
    prio.set(n, cost.get(n) + best)
  }
  return { names, start, finish, depth, prio, total }
}

export function pack({ cost, deps }, { names, prio }, workers) {
  const freeAt = new Array(workers).fill(0)
  const ran = Array.from({ length: workers }, () => [])
