#!/usr/bin/env node
import { readFileSync } from 'node:fs'

const DEFAULT_PORT = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }
const UNRESERVED = /^[A-Za-z0-9\-._~]$/

class Fail extends Error {}

function parse(s) {
  const r = { scheme: undefined, authority: undefined, path: '', query: undefined, fragment: undefined }
  const m = /^[^:/?#]*:/.exec(s)
  if (m) { r.scheme = m[0].slice(0, -1); s = s.slice(m[0].length) }
  const h = s.indexOf('#')
  if (h >= 0) { r.fragment = s.slice(h + 1); s = s.slice(0, h) }
  const q = s.indexOf('?')
  if (q >= 0) { r.query = s.slice(q + 1); s = s.slice(0, q) }
  if (s.startsWith('//')) {
    s = s.slice(2)
    const e = s.search(/[/]/)
    r.authority = e >= 0 ? s.slice(0, e) : s
    s = e >= 0 ? s.slice(e) : ''
  }
  r.path = s
  return r
}

function splitAuthority(a) {
  const at = a.lastIndexOf('@')
  const userinfo = at >= 0 ? a.slice(0, at) : undefined
  const rest = a.slice(at + 1)
  const from = rest.lastIndexOf(']')
  const c = rest.indexOf(':', from + 1)
  if (c >= 0) return { userinfo, host: rest.slice(0, c), port: rest.slice(c + 1) }
  return { userinfo, host: rest, port: undefined }
}

function removeDots(path) {
  let inp = path, out = ''
  while (inp.length) {
    if (inp.startsWith('../')) inp = inp.slice(3)
    else if (inp.startsWith('./')) inp = inp.slice(2)
    else if (inp.startsWith('/./')) inp = inp.slice(2)
    else if (inp === '/.') inp = '/'
    else if (inp.startsWith('/../') || inp === '/..') {
      inp = inp === '/..' ? '/' : inp.slice(3)
      out = out.slice(0, Math.max(0, out.lastIndexOf('/')))
    } else if (inp === '.' || inp === '..') inp = ''
    else {
      const i = inp.indexOf('/', 1)
      const seg = i >= 0 ? inp.slice(0, i) : inp
      out += seg
      inp = inp.slice(seg.length)
    }
  }
  return out
}

function pct(s) {
  return s.replace(/%([0-9A-Fa-f]{2})/g, (_, h) => {
    const ch = String.fromCharCode(parseInt(h, 16))
    return UNRESERVED.test(ch) ? ch : '%' + h.toUpperCase()
  })
}

const lowerAscii = (s) => s.replace(/[A-Z]/g, (c) => c.toLowerCase())

function serialize(t) {
  let out = ''
  if (t.scheme !== undefined) out += t.scheme + ':'
  if (t.authority !== undefined) out += '//' + t.authority
  out += t.path
  if (t.query !== undefined) out += '?' + t.query
  if (t.fragment !== undefined) out += '#' + t.fragment
  return out
}

function normalize(t, line) {
  const a = t.authority !== undefined ? splitAuthority(t.authority) : undefined
  const checks = [['path', t.path], ['userinfo', a?.userinfo], ['host', a?.host], ['query', t.query], ['fragment', t.fragment]]
  for (const [name, v] of checks) {
    if (v !== undefined && /%(?![0-9A-Fa-f]{2})/.test(v)) throw new Fail(`error: line ${line}: the ${name} has a truncated percent-encoding`)
  }
  const scheme = t.scheme === undefined ? undefined : lowerAscii(t.scheme)
  const r = { scheme, path: removeDots(pct(t.path)), query: t.query === undefined ? undefined : pct(t.query), fragment: t.fragment === undefined ? undefined : pct(t.fragment) }
  if (a) {
    let auth = ''
    if (a.userinfo !== undefined) auth += pct(a.userinfo) + '@'
    auth += lowerAscii(pct(a.host))
    let port = a.port === undefined ? undefined : pct(a.port)
    if (port === '' || (scheme !== undefined && port === DEFAULT_PORT[scheme])) port = undefined
    if (port !== undefined) auth += ':' + port
    r.authority = auth
    if (r.path === '') r.path = '/'
  }
  return serialize(r)
}

function resolve(base, ref) {
  if (ref.scheme !== undefined) return { ...ref, path: removeDots(ref.path) }
  const t = { scheme: base.scheme, fragment: ref.fragment }
  if (ref.authority !== undefined) {
    t.authority = ref.authority; t.path = removeDots(ref.path); t.query = ref.query
  } else {
    t.authority = base.authority
    if (ref.path === '') {
      t.path = base.path
      t.query = ref.query !== undefined ? ref.query : base.query
    } else {
      if (ref.path.startsWith('/')) t.path = removeDots(ref.path)
      else {
        let merged
        if (base.authority !== undefined && base.path === '') merged = '/' + ref.path
        else {
          const i = base.path.lastIndexOf('/')
          merged = i >= 0 ? base.path.slice(0, i + 1) + ref.path : ref.path
        }
        t.path = removeDots(merged)
      }
      t.query = ref.query
    }
  }
  return t
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    throw new Fail('error: usage: cli.js normalize|resolve')
  }
  const lines = readFileSync(0, 'utf8').split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const out = []
  lines.forEach((rec, i) => {
    const n = i + 1
    if (args[0] === 'normalize') { out.push(normalize(parse(rec), n)); return }
    const sp = rec.indexOf(' ')
    if (sp < 0) throw new Fail(`error: line ${n}: expected a base and a reference`)
    const base = parse(rec.slice(0, sp))
    if (base.scheme === undefined) throw new Fail(`error: line ${n}: the base has no scheme`)
    out.push(normalize(resolve(base, parse(rec.slice(sp + 1))), n))
  })
  if (out.length) process.stdout.write(out.join('\n') + '\n')
}

try { main() } catch (e) {
  if (!(e instanceof Fail)) throw e
  process.stderr.write(e.message + '\n')
  process.exitCode = 2
}
